// test/util.ts
var DEFAULT_URI = "file:///test.zx";
function makeDoc(content, version = 1, uri2 = DEFAULT_URI) {
  const lines2 = content.split(/\r?\n/);
  return {
    uri: uri2,
    path: "test.zx",
    languageId: "zornux",
    version,
    getText: () => content,
    lineCount: () => lines2.length,
    lineAt: (line) => lines2[line] ?? ""
  };
}
