// src/renderer/solution/solutionModel.ts
function baseName(path2) {
  return path2.split(/[\\/]/).filter(Boolean).pop() ?? path2;
}
function toProject(folder2) {
  const project = folder2.project;
  return {
    root: folder2.root,
    name: project?.name ?? baseName(folder2.root),
    type: folder2.detectedType,
    isProject: folder2.isZnxStudioProject,
    version: project?.version ?? null,
    targets: [...project?.languageTargets ?? [], ...project?.frameworkTargets ?? []],
    scripts: Object.keys(project?.scripts ?? {}),
    problemCount: folder2.diagnostics.length
  };
}
function buildSolution(folders, solutionName) {
  const projects = folders.map(toProject);
  const name = solutionName ?? projects.find((project) => project.isProject)?.name ?? projects[0]?.name ?? "Workspace";
  return {
    name,
    projects,
    projectCount: projects.filter((project) => project.isProject).length
  };
}

