function parsePackageDiagnostics(stdout) {
  const trimmed = stdout.trim();
  if (!trimmed.startsWith("[")) return [];
  try {
    const parsed = JSON.parse(trimmed);
    if (!Array.isArray(parsed)) return [];
    return parsed.map((entry4) => {
      const raw2 = entry4;
      return {
        code: raw2.code ?? raw2.Code ?? "",
        message: raw2.message ?? raw2.Message ?? "",
        help: raw2.help ?? raw2.Help
      };
    });
  } catch {
    return [];
  }
}
function interpretPackageOutput(exitCode, stdout, stderr) {
  if (exitCode === 0) {
    return { success: true, message: stdout.trim(), diagnostics: [] };
  }
  const diagnostics = parsePackageDiagnostics(stdout);
  const message = diagnostics.length > 0 ? "" : stderr.trim() || stdout.trim() || `Package command failed (exit ${exitCode}).`;
  return { success: false, message, diagnostics };
}

// test/packageprotocol.test.ts
describe("interpretPackageOutput", () => {
  test("exit 0 is success with the stdout message", () => {
    const result4 = interpretPackageOutput(0, "Added MathTools 1.2.0\n", "");
    expect(result4.success).toBeTruthy();
    expect(result4.message).toBe("Added MathTools 1.2.0");
    expect(result4.diagnostics).toHaveLength(0);
  });
  test("exit 0 under --json (no output) is still success", () => {
    const result4 = interpretPackageOutput(0, "", "");
    expect(result4.success).toBeTruthy();
    expect(result4.message).toBe("");
  });
  test("parses the --json failure diagnostics array (camelCase)", () => {
    const json = JSON.stringify([
      { code: "ZP2001", message: "Package 'Nope' was not found.", help: "check the name" },
      { code: "ZP2002", message: "Registry store is not configured." }
    ]);
    const result4 = interpretPackageOutput(1, json, "");
    expect(result4.success).toBeFalsy();
    expect(result4.diagnostics).toHaveLength(2);
    expect(result4.diagnostics[0].code).toBe("ZP2001");
    expect(result4.diagnostics[0].help).toBe("check the name");
    expect(result4.diagnostics[1].help).toBeFalsy();
  });
  test("tolerates PascalCase diagnostic keys", () => {
    const result4 = interpretPackageOutput(1, JSON.stringify([{ Code: "ZP1", Message: "boom" }]), "");
    expect(result4.diagnostics[0].code).toBe("ZP1");
    expect(result4.diagnostics[0].message).toBe("boom");
  });
  test("falls back to stderr when a failure is not JSON", () => {
    const result4 = interpretPackageOutput(3, "not json", "something broke");
    expect(result4.success).toBeFalsy();
    expect(result4.diagnostics).toHaveLength(0);
    expect(result4.message).toBe("something broke");
  });
  test("failure with no output still yields a message", () => {
    const result4 = interpretPackageOutput(1, "", "");
    expect(result4.success).toBeFalsy();
    expect(result4.message).toContain("exit 1");
  });
});

