// src/renderer/wizards/wizardModel.ts
var Wizard = class {
  constructor(steps, currentState) {
    this.steps = steps;
    this.currentState = currentState;
    if (steps.length === 0) throw new Error("A wizard needs at least one step.");
  }
  index = 0;
  get state() {
    return this.currentState;
  }
  current() {
    return this.steps[this.index];
  }
  stepNumber() {
    return this.index + 1;
  }
  total() {
    return this.steps.length;
  }
  isFirst() {
    return this.index === 0;
  }
  isLast() {
    return this.index === this.steps.length - 1;
  }
  /** The current step's validation error, or null when it is satisfied. */
  error() {
    return this.current().validate?.(this.currentState) ?? null;
  }
  canAdvance() {
    return this.error() === null;
  }
  /** Advance to the next step; no-op (returns false) if invalid or already last. */
  next() {
    if (this.isLast() || !this.canAdvance()) return false;
    this.index += 1;
    return true;
  }
  back() {
    if (this.isFirst()) return false;
    this.index -= 1;
    return true;
  }
  /** True only when the last step is reached and valid. */
  canFinish() {
    return this.isLast() && this.canAdvance();
  }
  update(patch) {
    this.currentState = { ...this.currentState, ...patch };
  }
};

// src/renderer/wizards/newProjectWizard.ts
function initialNewProjectState() {
  return { templateId: null, name: "", location: null, dependencies: [], profile: "development" };
}
var NAME_PATTERN = /^[A-Za-z][A-Za-z0-9._-]*$/;
function validateProjectName(name) {
  const trimmed = name.trim();
  if (!trimmed) return "Enter a project name.";
  if (!NAME_PATTERN.test(trimmed)) {
    return "Use letters, digits, '.', '-', or '_', starting with a letter.";
  }
  return null;
}
function parseDependencySpec(spec) {
  const trimmed = spec.trim();
  if (!trimmed) return "A dependency cannot be empty.";
  const at = trimmed.indexOf("@");
  if (at < 0) return { name: trimmed };
  const name = trimmed.slice(0, at);
  const version = trimmed.slice(at + 1);
  if (!name) return 'A dependency needs a name before "@".';
  if (!version) return 'A dependency version cannot be empty (drop the "@" to take the latest).';
  return { name, version };
}
function newProjectSteps() {
  return [
    {
      id: "template",
      title: "Choose a template",
      validate: (state) => state.templateId && findTemplate(state.templateId) ? null : "Select a template to continue."
    },
    {
      id: "details",
      title: "Name & location",
      validate: (state) => validateProjectName(state.name) ?? (state.location ? null : "Choose a location folder.")
    },
    {
      id: "dependencies",
      title: "Dependencies (optional)",
      validate: (state) => {
        for (const spec of state.dependencies) {
          const parsed = parseDependencySpec(spec);
          if (typeof parsed === "string") return parsed;
        }
        return null;
      }
    },
    {
      id: "profile",
      title: "Environment profile",
      validate: (state) => ENVIRONMENT_PROFILES.includes(state.profile) ? null : "Pick a valid profile."
    },
    { id: "review", title: "Review & create" }
  ];
}
function buildNewProjectPlan(state) {
  const template = state.templateId ? findTemplate(state.templateId) : void 0;
  if (!template) throw new Error("No template selected.");
  if (!state.location) throw new Error("No location selected.");
  const name = state.name.trim();
  const rendered = renderTemplate(template, name);
  const dependencies = state.dependencies.map((spec) => spec.trim()).filter(Boolean);
  const requiresCompiler = rendered.runZornuxInit || dependencies.length > 0;
  return {
    scaffold: { name, location: state.location, runZornuxInit: rendered.runZornuxInit, files: rendered.files },
    requiresCompiler,
    dependencies,
    profile: state.profile
  };
}

// test/wizard.test.ts
function counterSteps() {
  return [
    { id: "a", title: "A", validate: (s) => s.value >= 1 ? null : "need >= 1" },
    { id: "b", title: "B" },
    { id: "c", title: "C", validate: (s) => s.value >= 3 ? null : "need >= 3" }
  ];
}
describe("Wizard engine", () => {
  test("starts on the first step and blocks advancing when invalid", () => {
    const w = new Wizard(counterSteps(), { value: 0 });
    expect(w.isFirst()).toBeTruthy();
    expect(w.stepNumber()).toBe(1);
    expect(w.canAdvance()).toBeFalsy();
    expect(w.next()).toBeFalsy();
    expect(w.stepNumber()).toBe(1);
  });
  test("advances once the current step validates", () => {
    const w = new Wizard(counterSteps(), { value: 0 });
    w.update({ value: 2 });
    expect(w.canAdvance()).toBeTruthy();
    expect(w.next()).toBeTruthy();
    expect(w.stepNumber()).toBe(2);
    expect(w.back()).toBeTruthy();
    expect(w.isFirst()).toBeTruthy();
  });
  test("canFinish only on a valid last step", () => {
    const w = new Wizard(counterSteps(), { value: 2 });
    w.next();
    w.next();
    expect(w.isLast()).toBeTruthy();
    expect(w.canFinish()).toBeFalsy();
    w.update({ value: 3 });
    expect(w.canFinish()).toBeTruthy();
  });
  test("back on the first step is a no-op", () => {
    const w = new Wizard(counterSteps(), { value: 5 });
    expect(w.back()).toBeFalsy();
  });
});
describe("New Project wizard model", () => {
  test("validateProjectName enforces a sane identifier", () => {
    expect(validateProjectName("")).toContain("Enter");
    expect(validateProjectName("9lives")).toContain("starting with a letter");
    expect(validateProjectName("my-app_1.0")).toBeNull();
  });
  test("parseDependencySpec splits name and version, and rejects malformed input", () => {
    expect(parseDependencySpec("MathTools")).toEqual({ name: "MathTools" });
    expect(parseDependencySpec("MathTools@1.2.0")).toEqual({ name: "MathTools", version: "1.2.0" });
    expect(typeof parseDependencySpec("")).toBe("string");
    expect(typeof parseDependencySpec("MathTools@")).toBe("string");
  });
  test("step validators gate each stage of the flow", () => {
    const steps = newProjectSteps();
    const state = initialNewProjectState();
    expect(steps[0].validate?.(state)).toContain("Select a template");
    state.templateId = "zornux-cli";
    expect(steps[0].validate?.(state)).toBeNull();
    expect(steps[1].validate?.(state)).toContain("Enter a project name");
    state.name = "demo";
    expect(steps[1].validate?.(state)).toContain("location");
    state.location = "C:/tmp";
    expect(steps[1].validate?.(state)).toBeNull();
    state.dependencies = ["bad@"];
    expect(steps[2].validate?.(state)).toBeTruthy();
    state.dependencies = ["MathTools@1.0.0"];
    expect(steps[2].validate?.(state)).toBeNull();
  });
  test("buildNewProjectPlan composes scaffold + deps + profile", () => {
    const state = {
      templateId: "zornux-cli",
      name: "demo",
      location: "C:/tmp",
      dependencies: ["MathTools@1.0.0", "  "],
      profile: "production"
    };
    const plan = buildNewProjectPlan(state);
    expect(plan.scaffold.name).toBe("demo");
    expect(plan.scaffold.location).toBe("C:/tmp");
    expect(plan.scaffold.runZornuxInit).toBeTruthy();
    expect(plan.requiresCompiler).toBeTruthy();
    expect(plan.dependencies).toHaveLength(1);
    expect(plan.dependencies[0]).toBe("MathTools@1.0.0");
    expect(plan.profile).toBe("production");
  });
  test("a files-only template with no deps needs no compiler", () => {
    const plan = buildNewProjectPlan({
      templateId: "zoijs-frontend",
      name: "web",
      location: "C:/tmp",
      dependencies: [],
      profile: "development"
    });
    expect(plan.scaffold.runZornuxInit).toBeFalsy();
    expect(plan.requiresCompiler).toBeFalsy();
  });
});

// src/renderer/zoijs/zoijsDetect.ts
