// src/renderer/productivity/todoScan.ts
var TASK_TAGS = ["TODO", "FIXME", "HACK", "XXX", "BUG", "NOTE"];
var TASK_TAG_REGEX = `\\b(${TASK_TAGS.join("|")})\\b`;
