function parseTaskTag(line) {
  const match2 = LINE_RE.exec(line);
  if (!match2) return null;
  const tag = match2[1];
  const before = line.slice(0, line.indexOf(tag, match2.index));
  if (!COMMENT_MARKER.test(before)) return null;
  const message = match2[2].replace(/\*\/\s*$/, "").trim();
  return { tag, message };
}

// test/productivity.test.ts
describe("fuzzyMatch", () => {
  test("matches a subsequence and records positions", () => {
    const m = fuzzyMatch("abc", "axbxc");
    expect(m === null).toBe(false);
    expect(m.positions).toEqual([0, 2, 4]);
  });
  test("returns null when a char is missing", () => {
    expect(fuzzyMatch("xyz", "abc")).toBeNull();
  });
  test("empty query matches anything", () => {
    expect(fuzzyMatch("", "anything").positions).toHaveLength(0);
  });
  test("a consecutive run scores higher than a scattered match", () => {
    const consecutive = fuzzyMatch("app", "application").score;
    const scattered = fuzzyMatch("app", "axpxplication").score;
    expect(consecutive).toBeGreaterThan(scattered);
  });
  test("is case-insensitive", () => {
    expect(fuzzyMatch("ABC", "aabbcc") === null).toBe(false);
  });
});
describe("fuzzyFilter", () => {
  test("ranks basename matches above deep-path matches", () => {
    const files = ["src/util/config.ts", "src/config/index.ts", "src/main.ts"];
    const ranked = fuzzyFilter("config", files, (f) => f).map((r) => r.item);
    expect(ranked[0]).toBe("src/util/config.ts");
    expect(ranked.includes("src/main.ts")).toBe(false);
  });
  test("drops non-matching items", () => {
    expect(fuzzyFilter("zzz", ["abc", "def"], (f) => f)).toHaveLength(0);
  });
});
describe("parseTaskTag", () => {
  test("parses a tag + message from a comment", () => {
    expect(parseTaskTag("# TODO: fix the walk")).toEqual({ tag: "TODO", message: "fix the walk" });
    expect(parseTaskTag("    // FIXME - broken")).toEqual({ tag: "FIXME", message: "broken" });
    expect(parseTaskTag(" * HACK temporary")).toEqual({ tag: "HACK", message: "temporary" });
  });
  test("ignores tags inside strings or identifiers", () => {
    expect(parseTaskTag('create x = "TODO later"')).toBeNull();
    expect(parseTaskTag("const aTODOx = 1")).toBeNull();
  });
  test("strips a trailing block-comment close", () => {
    expect(parseTaskTag("/* BUG double free */")).toEqual({ tag: "BUG", message: "double free" });
  });
  test("the tag regex names every tag", () => {
    expect(TASK_TAG_REGEX).toContain("TODO");
    expect(TASK_TAG_REGEX).toContain("FIXME");
  });
});

// src/renderer/database/databaseModel.ts
var DATABASE_RE = /^database\s+([A-Za-z_]\w*)/;
var PROVIDER_RE = /^provider\s+([A-Za-z_]\w*)/;
var CONNECTION_RE = /^connection\s+"([^"]*)"/;
var TABLE_RE = /^table\s+([A-Za-z_]\w*)\s+from\s+([A-Za-z_]\w*)/;
var MIGRATE_RE = /^migrate\s+on\s+open\b/;
function parseDatabaseBlocks(text) {
  const lines2 = text.split(/\r?\n/);
  const blocks = [];
  for (let i = 0; i < lines2.length; i += 1) {
    const header = DATABASE_RE.exec(lines2[i]);
    if (!header) continue;
    const connection = {
      name: header[1],
      provider: "unknown",
      tables: [],
      migrateOnOpen: false,
      line: i
    };
    let j = i + 1;
    for (; j < lines2.length; j += 1) {
      const trimmed = lines2[j].trim();
      if (trimmed === "end" || /^end\b/.test(trimmed)) break;
      const provider = PROVIDER_RE.exec(trimmed);
      if (provider) {
        connection.provider = provider[1];
        continue;
      }
      const conn = CONNECTION_RE.exec(trimmed);
      if (conn) {
        connection.connection = conn[1];
        continue;
      }
      const table = TABLE_RE.exec(trimmed);
      if (table) {
        connection.tables.push({ table: table[1], from: table[2] });
        continue;
      }
      if (MIGRATE_RE.test(trimmed)) connection.migrateOnOpen = true;
    }
    blocks.push(connection);
    i = j;
  }
  return blocks;
}
function isFileBackedProvider(provider) {
  return provider.toLowerCase() === "sqlite";
}
function describeTarget(connection) {
  if (connection.connection) return connection.connection;
  return connection.provider === "memory" ? "in-memory (ephemeral)" : "(no connection string)";
}

// test/database.test.ts
var DURABLE = `class Note
    has id
    has title
end

database Notebook
    provider sqlite
    connection "store.sqlite"
    table Notes from Note
    migrate on open
end
`;
var MULTI = `database AppDb
    provider memory
    table Users from User
    table Sessions from Session
end

database Analytics
    provider sqlite
    connection "metrics.db"
    table Events from Event
end
`;
describe("parseDatabaseBlocks", () => {
  test("parses a full sqlite database block", () => {
    const blocks = parseDatabaseBlocks(DURABLE);
    expect(blocks).toHaveLength(1);
    const db = blocks[0];
    expect(db.name).toBe("Notebook");
    expect(db.provider).toBe("sqlite");
    expect(db.connection).toBe("store.sqlite");
    expect(db.tables).toEqual([{ table: "Notes", from: "Note" }]);
    expect(db.migrateOnOpen).toBe(true);
    expect(db.line).toBe(5);
  });
  test("parses multiple databases and multiple tables", () => {
    const blocks = parseDatabaseBlocks(MULTI);
    expect(blocks).toHaveLength(2);
    expect(blocks[0].name).toBe("AppDb");
    expect(blocks[0].tables).toHaveLength(2);
    expect(blocks[0].tables[1]).toEqual({ table: "Sessions", from: "Session" });
    expect(blocks[1].name).toBe("Analytics");
    expect(blocks[1].connection).toBe("metrics.db");
  });
  test("a memory database has no connection string and migrate defaults false", () => {
    const blocks = parseDatabaseBlocks("database D\n    provider memory\n    table T from C\nend\n");
    expect(blocks[0].connection).toBeFalsy();
    expect(blocks[0].migrateOnOpen).toBe(false);
    expect(blocks[0].provider).toBe("memory");
  });
  test("no database blocks yields an empty list", () => {
    expect(parseDatabaseBlocks("class X\n    has y\nend\n")).toHaveLength(0);
  });
});
describe("helpers", () => {
  test("isFileBackedProvider is true only for sqlite", () => {
    expect(isFileBackedProvider("sqlite")).toBe(true);
    expect(isFileBackedProvider("SQLite")).toBe(true);
    expect(isFileBackedProvider("memory")).toBe(false);
  });
  test("describeTarget prefers the connection string, else summarises", () => {
    const blocks = parseDatabaseBlocks(MULTI);
    expect(describeTarget(blocks[0])).toBe("in-memory (ephemeral)");
    expect(describeTarget(blocks[1])).toBe("metrics.db");
  });
});

