// test/query.test.ts
describe("parseQuery \u2014 find", () => {
  test("parses a simple find all", () => {
    const q = parseQuery("find all from Db.People");
    expect(q.ok).toBe(true);
    expect(q.kind).toBe("find");
    expect(q.resultMode).toBe("all");
    expect(q.database).toBe("Db");
    expect(q.table).toBe("People");
    expect(q.where).toHaveLength(0);
  });
  test("parses where with a multi-word operator", () => {
    const q = parseQuery("find count from Db.People where age is greater than or equal to 18");
    expect(q.resultMode).toBe("count");
    expect(q.where).toHaveLength(1);
    expect(q.where[0]).toEqual({
      field: "age",
      operator: "is greater than or equal to",
      value: "18",
      connector: null
    });
  });
  test("parses and/or conditions, sorted by, and first", () => {
    const q = parseQuery('find all from Db.People where city is "London" and age is greater than 20 sorted by age descending first 2');
    expect(q.where).toHaveLength(2);
    expect(q.where[0]).toEqual({ field: "city", operator: "is", value: '"London"', connector: null });
    expect(q.where[1]).toEqual({ field: "age", operator: "is greater than", value: "20", connector: "and" });
    expect(q.sortBy).toBe("age");
    expect(q.sortDir).toBe("descending");
    expect(q.limit).toBe(2);
  });
});
describe("parseQuery \u2014 aggregate + errors", () => {
  test("parses an aggregate", () => {
    const q = parseQuery("average of age from Db.People");
    expect(q.kind).toBe("aggregate");
    expect(q.aggregate).toBe("average");
    expect(q.aggregateField).toBe("age");
    expect(q.table).toBe("People");
  });
  test("rejects a non-query", () => {
    expect(parseQuery("select * from users").ok).toBe(false);
    expect(parseQuery("").ok).toBe(false);
  });
  test("rejects a bad source", () => {
    expect(parseQuery("find all from People").ok).toBe(false);
  });
});
describe("validateQuery", () => {
  const cols = { People: ["name", "age", "city"] };
  test("accepts a well-formed query", () => {
    expect(validateQuery(parseQuery("find all from Db.People where age is greater than 10"), cols)).toHaveLength(0);
  });
  test("flags an unknown table", () => {
    expect(validateQuery(parseQuery("find all from Db.Ghost"), cols)[0]).toContain("Unknown table");
  });
  test("flags unknown fields in where and sort", () => {
    const diags = validateQuery(parseQuery("find all from Db.People where nope is 1 sorted by bad"), cols);
    expect(diags).toHaveLength(2);
    expect(diags[0]).toContain("nope");
    expect(diags[1]).toContain("bad");
  });
});
describe("whereClause + buildRunExpression", () => {
  test("reconstructs a where clause", () => {
    const q = parseQuery('find one from Db.People where age is 5 and city is "X"');
    expect(whereClause(q.where)).toBe(' where age is 5 and city is "X"');
  });
  test("find of any mode becomes find count", () => {
    expect(buildRunExpression(parseQuery("find all from Db.People where age is greater than 18"))).toBe(
      "find count from Db.People where age is greater than 18"
    );
  });
  test("aggregate stays itself", () => {
    expect(buildRunExpression(parseQuery("sum of age from Db.People"))).toBe("sum of age from Db.People");
  });
});

// src/renderer/database/migrationModel.ts
var MIGRATION_RE = /^migration\s+([A-Za-z_]\w*)/;
var CREATE_TABLE_RE = /^create\s+table\s+([A-Za-z_]\w*)\s+from\s+([A-Za-z_]\w*)/;
var ADD_FIELD_RE = /^add\s+field\s+([A-Za-z_]\w*)\s+to\s+([A-Za-z_]\w*)/;
function parseMigrations(text) {
  const lines2 = text.split(/\r?\n/);
  const migrations = [];
  for (let i = 0; i < lines2.length; i += 1) {
    const header = MIGRATION_RE.exec(lines2[i]);
    if (!header) continue;
    const operations = [];
    let j = i + 1;
    for (; j < lines2.length; j += 1) {
      if (/^end\b/.test(lines2[j])) break;
      const trimmed = lines2[j].trim();
      if (trimmed === "" || trimmed.startsWith("#")) continue;
      operations.push(parseOperation(trimmed));
    }
    migrations.push({ name: header[1], operations, line: i });
    i = j;
  }
  return migrations;
}
function parseOperation(text) {
  const create = CREATE_TABLE_RE.exec(text);
  if (create) return { kind: "create-table", text, table: create[1], from: create[2] };
  const add = ADD_FIELD_RE.exec(text);
  if (add) return { kind: "add-field", text, field: add[1], table: add[2] };
  return { kind: "other", text };
}
function statusList(value) {
  const trimmed = value.trim();
  if (trimmed === "" || trimmed.toLowerCase() === "none") return [];
  return trimmed.split(",").map((item) => item.trim()).filter(Boolean);
}
function parseDbStatus(output) {
  const statuses = [];
  let current = null;
  for (const raw2 of output.split(/\r?\n/)) {
    const header = /^([A-Za-z_]\w*):\s*$/.exec(raw2);
    if (header) {
      current = { database: header[1], applied: [], pending: [] };
      statuses.push(current);
      continue;
    }
    if (!current) continue;
    const applied = /^\s+applied\s+\(\d+\):\s*(.*)$/.exec(raw2);
    if (applied) {
      current.applied = statusList(applied[1]);
      continue;
    }
    const pending = /^\s+pending\s+\(\d+\):\s*(.*)$/.exec(raw2);
    if (pending) current.pending = statusList(pending[1]);
  }
  return statuses;
}
function generateMigration(spec) {
  const operation = spec.kind === "create-table" ? `create table ${spec.table} from ${spec.from}` : `add field ${spec.field} to ${spec.table}`;
  return `migration ${spec.name}
    ${operation}
end
`;
}

// test/migration.test.ts
var SOURCE2 = `class Product
    has id
    has name
end

migration CreateProducts
    create table Products from Product
end

migration AddSku
    # add a stock-keeping unit
    add field sku to Products
end

database Store
    provider memory
    table Products from Product
    migrate on open
end
`;
describe("parseMigrations", () => {
  test("parses ordered migration blocks with operations", () => {
    const migrations = parseMigrations(SOURCE2);
    expect(migrations.map((m) => m.name)).toEqual(["CreateProducts", "AddSku"]);
    expect(migrations[0].operations[0]).toEqual({
      kind: "create-table",
      text: "create table Products from Product",
      table: "Products",
      from: "Product"
    });
  });
  test("parses add-field and skips comments", () => {
    const addSku = parseMigrations(SOURCE2)[1];
    expect(addSku.operations).toHaveLength(1);
    expect(addSku.operations[0]).toEqual({
      kind: "add-field",
      text: "add field sku to Products",
      field: "sku",
      table: "Products"
    });
  });
  test("no migrations yields an empty list", () => {
    expect(parseMigrations("class X\n    has y\nend\n")).toHaveLength(0);
  });
});
describe("parseDbStatus", () => {
  test("parses applied and pending lists", () => {
    const statuses = parseDbStatus("Store:\n  applied (1): CreateProducts\n  pending (1): AddSku\n");
    expect(statuses).toHaveLength(1);
    expect(statuses[0].database).toBe("Store");
    expect(statuses[0].applied).toEqual(["CreateProducts"]);
    expect(statuses[0].pending).toEqual(["AddSku"]);
  });
  test('treats "none" as empty', () => {
    const statuses = parseDbStatus("Store:\n  applied (0): none\n  pending (2): A, B\n");
    expect(statuses[0].applied).toHaveLength(0);
    expect(statuses[0].pending).toEqual(["A", "B"]);
  });
  test("handles multiple databases", () => {
    const statuses = parseDbStatus("A:\n  applied (0): none\n  pending (0): none\nB:\n  applied (1): X\n  pending (0): none\n");
    expect(statuses.map((s) => s.database)).toEqual(["A", "B"]);
    expect(statuses[1].applied).toEqual(["X"]);
  });
});
describe("generateMigration", () => {
  test("generates a create-table migration", () => {
    expect(generateMigration({ name: "CreateUsers", kind: "create-table", table: "Users", from: "User" })).toBe(
      "migration CreateUsers\n    create table Users from User\nend\n"
    );
  });
  test("generates an add-field migration", () => {
    expect(generateMigration({ name: "AddEmail", kind: "add-field", field: "email", table: "Users" })).toBe(
      "migration AddEmail\n    add field email to Users\nend\n"
    );
  });
});

// src/renderer/database/dataBrowser.ts
var ROW_MARK = "__ROW__";
var CELL_SEP = "<|>";
function buildBrowseProgram(source, database, table, columns) {
  const cells = columns.map((column) => `text(row.${column})`).join(` + "${CELL_SEP}" + `);
  const show = cells === "" ? `"${ROW_MARK}"` : `"${ROW_MARK}" + ${cells}`;
  return `${source}
for each row in find all from ${database}.${table}
    show ${show}
end
`;
}
function parseRows(output) {
  const rows = [];
  for (const line of output.split(/\r?\n/)) {
    const index = line.indexOf(ROW_MARK);
    if (index === -1) continue;
    const rest = line.slice(index + ROW_MARK.length);
    rows.push(rest === "" ? [] : rest.split(CELL_SEP));
  }
  return rows;
}

// test/databrowser.test.ts
describe("buildBrowseProgram", () => {
  test("appends a print loop over the table columns", () => {
    const program = buildBrowseProgram("# seed", "Db", "People", ["id", "name", "age"]);
    expect(program).toContain("# seed");
    expect(program).toContain("for each row in find all from Db.People");
    expect(program).toContain(`show "${ROW_MARK}" + text(row.id) + "${CELL_SEP}" + text(row.name) + "${CELL_SEP}" + text(row.age)`);
  });
  test("handles a single column", () => {
    expect(buildBrowseProgram("x", "D", "T", ["id"])).toContain(`show "${ROW_MARK}" + text(row.id)`);
  });
  test("handles no columns", () => {
    expect(buildBrowseProgram("x", "D", "T", [])).toContain(`show "${ROW_MARK}"`);
  });
});
describe("parseRows", () => {
  test("extracts marker lines into cells and ignores other output", () => {
    const output = ["Products: 4", `${ROW_MARK}1${CELL_SEP}Ada${CELL_SEP}36`, "noise", `${ROW_MARK}2${CELL_SEP}Bob${CELL_SEP}17`].join("\n");
    expect(parseRows(output)).toEqual([
      ["1", "Ada", "36"],
      ["2", "Bob", "17"]
    ]);
  });
  test("a marker with no cells yields an empty row", () => {
    expect(parseRows(`${ROW_MARK}`)).toEqual([[]]);
  });
  test("no markers yields no rows", () => {
    expect(parseRows("nothing here\nat all")).toHaveLength(0);
  });
});

// src/renderer/database/profiler.ts
var PROFILE_MARK = "__PROF__";
function buildProfileProgram(source, runExpr, iterations) {
  return `${source}
create zprof_total = 0
create zprof_began = current_datetime()
repeat ${iterations} times
    zprof_total = zprof_total + (${runExpr})
end
show "${PROFILE_MARK}" + text(elapsed_time(zprof_began)) + "|" + text(zprof_total)
`;
}
function parseProfile(output) {
  const match2 = new RegExp(`${PROFILE_MARK}([\\d.]+)\\|(.+)`).exec(output);
  if (!match2) return null;
  return { seconds: Number(match2[1]), result: match2[2].trim() };
}
function perQueryMicros(seconds, iterations) {
  if (iterations <= 0) return 0;
  return seconds / iterations * 1e6;
}
function clampIterations(value) {
  if (!Number.isFinite(value) || value < 1) return 1;
  return Math.min(Math.floor(value), 1e5);
}

// test/queryprofiler.test.ts
describe("buildProfileProgram", () => {
  test("wraps the query in a timed loop", () => {
    const program = buildProfileProgram("# seed", "find count from Db.People", 500);
    expect(program).toContain("# seed");
    expect(program).toContain("create zprof_began = current_datetime()");
    expect(program).toContain("repeat 500 times");
    expect(program).toContain("zprof_total = zprof_total + (find count from Db.People)");
    expect(program).toContain(`show "${PROFILE_MARK}" + text(elapsed_time(zprof_began))`);
  });
});
describe("parseProfile", () => {
  test("extracts seconds and the accumulator", () => {
    const sample = parseProfile("People: 4\n__PROF__0.0108789|6000\n");
    expect(sample).toEqual({ seconds: 0.0108789, result: "6000" });
  });
  test("returns null without a marker", () => {
    expect(parseProfile("no marker here")).toBeNull();
  });
  test("handles a fractional aggregate result", () => {
    expect(parseProfile("__PROF__0.5|29.5").result).toBe("29.5");
  });
});
describe("perQueryMicros", () => {
  test("computes mean microseconds per query", () => {
    expect(perQueryMicros(2e-3, 2e3)).toBe(1);
  });
  test("guards against zero iterations", () => {
    expect(perQueryMicros(1, 0)).toBe(0);
  });
});
describe("clampIterations", () => {
  test("clamps to [1, 100000] and floors", () => {
    expect(clampIterations(-5)).toBe(1);
    expect(clampIterations(0)).toBe(1);
    expect(clampIterations(3.9)).toBe(3);
    expect(clampIterations(1e9)).toBe(1e5);
    expect(clampIterations(NaN)).toBe(1);
  });
});

