var REFACTOR_ACTIONS = [
  {
    id: "rename",
    label: "Improve names",
    description: "Clearer variable / function / parameter names.",
    instruction: "Rename variables, functions, and parameters to be clearer and more descriptive. Do not change behavior."
  },
  {
    id: "extract",
    label: "Extract helpers",
    description: "Pull complex or repeated logic into named functions.",
    instruction: "Extract repeated or complex logic into well-named helper functions. Preserve behavior exactly."
  },
  {
    id: "simplify",
    label: "Simplify",
    description: "Remove redundancy and flatten nesting.",
    instruction: "Simplify the code: remove redundancy and dead code and flatten nesting, without changing behavior."
  },
  {
    id: "errors",
    label: "Add error handling",
    description: "Validate inputs and handle failure cases.",
    instruction: "Add appropriate error handling and input validation while preserving the existing happy-path behavior."
  },
  {
    id: "comments",
    label: "Add comments",
    description: "Explain the code with concise comments.",
    instruction: "Add concise explanatory comments. Do not change any executable code."
  },
  {
    id: "idiomatic",
    label: "Make idiomatic",
    description: "Rewrite as clearer, idiomatic Zornux.",
    instruction: "Rewrite to be more idiomatic and readable Zornux, preserving behavior. Keep English-readable keywords and column-0 `end`."
  },
  {
    id: "custom",
    label: "Custom instruction\u2026",
    description: "Describe the change in your own words.",
    instruction: "",
    custom: true
  }
];
function findRefactorAction(id) {
  return REFACTOR_ACTIONS.find((action) => action.id === id);
}
function buildRefactorMessages(action, code, fileName, customInstruction = "") {
  const instruction = action.custom ? customInstruction.trim() : action.instruction;
  const system = [
    "You are a code refactoring engine inside the ZnxStudio IDE for the Zornux language (.zx).",
    "Rewrite the user's selected code according to the instruction.",
    "Return ONLY the rewritten code that will replace the selection verbatim \u2014 no explanation, no Markdown code fences.",
    "Preserve program behavior unless the instruction explicitly says otherwise.",
    "Match the surrounding indentation and keep Zornux idioms (English-readable keywords, column-0 `end`)."
  ].join("\n");
  const where = fileName ? `File: ${fileName}
` : "";
  const user = `${where}Instruction: ${instruction || "(none)"}

Selected code:
${code}`;
  return { system, messages: [{ role: "user", content: user }] };
}
function stripCodeFences(text) {
  const fence = text.match(/^\s*```[^\n]*\n([\s\S]*?)\n?```\s*$/);
  return fence ? fence[1] : text;
}
function cleanRefactorOutput(raw2) {
  return stripCodeFences(raw2.replace(/\r\n/g, "\n")).replace(/^\n+/, "").replace(/\s+$/, "");
}
function diffLines(before, after) {
  const a = before.split("\n");
  const b = after.split("\n");
  const n = a.length;
  const m = b.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i2 = n - 1; i2 >= 0; i2--) {
    for (let j2 = m - 1; j2 >= 0; j2--) {
      dp[i2][j2] = a[i2] === b[j2] ? dp[i2 + 1][j2 + 1] + 1 : Math.max(dp[i2 + 1][j2], dp[i2][j2 + 1]);
    }
  }
  const out = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      out.push({ type: "context", text: a[i] });
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      out.push({ type: "del", text: a[i] });
      i++;
    } else {
      out.push({ type: "add", text: b[j] });
      j++;
    }
  }
  while (i < n) out.push({ type: "del", text: a[i++] });
  while (j < m) out.push({ type: "add", text: b[j++] });
  return out;
}
function diffStats(diff) {
  let added = 0;
  let removed = 0;
  for (const line of diff) {
    if (line.type === "add") added++;
    else if (line.type === "del") removed++;
  }
  return { added, removed };
}

