// src/renderer/ai/review.ts
var SEVERITY_RANK = { error: 0, warning: 1, info: 2, suggestion: 3 };
function numberLines(code, startLine = 1) {
  return code.split("\n").map((line, index) => `${startLine + index}: ${line}`).join("\n");
}
function buildReviewMessages(code, fileName, startLine = 1) {
  const system = [
    "You are a meticulous code reviewer inside the ZnxStudio IDE for the Zornux language (.zx).",
    "Review the code for bugs, correctness, missing edge cases, readability, and idiomatic style.",
    "Respond with ONLY a JSON array \u2014 no prose, no Markdown code fences.",
    'Each element: {"line": <number matching the shown line numbers>, "severity": "error"|"warning"|"info"|"suggestion", "title": <short>, "detail": <one or two sentences>}.',
    "Cite the most relevant line for each finding. If the code has no issues, return []."
  ].join("\n");
  const where = fileName ? `File: ${fileName}

` : "";
  const user = `${where}Review this code (line numbers shown):
${numberLines(code, startLine)}`;
  return { system, messages: [{ role: "user", content: user }] };
}
function normalizeSeverity2(value) {
  const v = String(value ?? "").toLowerCase();
  if (/(error|critical|high|bug|blocker)/.test(v)) return "error";
  if (/(warn|medium|major)/.test(v)) return "warning";
  if (/(suggest|hint|nit|style|minor|refactor)/.test(v)) return "suggestion";
  return "info";
}
function extractJsonArray(text) {
  const start = text.indexOf("[");
  const end = text.lastIndexOf("]");
  if (start < 0 || end <= start) return null;
  return text.slice(start, end + 1);
}
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}
function parseReviewFindings(text, bounds) {
  const json = extractJsonArray(text);
  if (!json) return [];
  let parsed;
  try {
    parsed = JSON.parse(json);
  } catch {
    return [];
  }
  if (!Array.isArray(parsed)) return [];
  const findings = [];
  for (const raw2 of parsed) {
    if (!raw2 || typeof raw2 !== "object") continue;
    const item = raw2;
    const title = String(item.title ?? item.message ?? "").trim();
    if (!title) continue;
    const lineValue = Number(item.line ?? item.lineNumber);
    const line = Number.isFinite(lineValue) ? clamp(Math.round(lineValue), bounds.minLine, bounds.maxLine) : bounds.minLine;
    findings.push({
      line,
      severity: normalizeSeverity2(item.severity),
      title,
      detail: String(item.detail ?? item.description ?? "").trim()
    });
  }
  return sortFindings(findings);
}
function sortFindings(findings) {
  return [...findings].sort((a, b) => a.line - b.line || SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity]);
}
function countBySeverity2(findings) {
  const counts = { error: 0, warning: 0, info: 0, suggestion: 0 };
  for (const finding5 of findings) counts[finding5.severity]++;
  return counts;
}
function reviewSeverityToDecoration(severity) {
  return severity === "suggestion" ? "hint" : severity;
}
function findingsToDecorations(findings) {
  return findings.map((finding5) => {
    const zeroLine = Math.max(0, finding5.line - 1);
    return {
      startLine: zeroLine,
      startCharacter: 0,
      endLine: zeroLine,
      endCharacter: 0,
      severity: reviewSeverityToDecoration(finding5.severity),
      inlineMessage: finding5.title,
      wholeLine: finding5.severity === "error" || finding5.severity === "warning"
    };
  });
}

