function formatDocComment(docText, indent) {
  const body2 = cleanDocText(docText).split("\n").map((line) => line.length ? `${indent}${COMMENT_PREFIX} ${line}` : `${indent}${COMMENT_PREFIX}`).join("\n");
  return `${body2}
`;
}
function hasDocCommentAbove(text, headerLine) {
  if (headerLine <= 0) return false;
  return new RegExp(`^\\s*${COMMENT_PREFIX}`).test(text.split("\n")[headerLine - 1] ?? "");
}

