// src/renderer/ai/testgen.ts
function buildTestGenMessages(code, fileName, target) {
  const system = [
    "You generate unit tests for the Zornux language (.zx).",
    "Zornux tests look like:",
    'test "describes the case"',
    "    expect <actual> to equal <expected>",
    "end",
    "The closing `end` is at column 0. Tests live in the same file as the code and call its functions directly.",
    "Write focused tests covering normal cases and important edge cases. Use clear descriptions.",
    "Output ONLY Zornux test blocks \u2014 no prose, no Markdown code fences, and do not restate the source code."
  ].join("\n");
  const where = fileName ? `File: ${fileName}
` : "";
  const focus = target ? `Focus on the function \`${target}\`.
` : "";
  const user = `${where}${focus}Write tests for this code:

${code}`;
  return { system, messages: [{ role: "user", content: user }] };
}
function stripFences3(text) {
  const fence = text.match(/^\s*```[^\n]*\n([\s\S]*?)\n?```\s*$/);
  return fence ? fence[1] : text;
}
function dedent(text) {
  const lines2 = text.split("\n");
  let min = Infinity;
  for (const line of lines2) {
    if (!line.trim()) continue;
    const indent = line.match(/^[ \t]*/)?.[0].length ?? 0;
    if (indent < min) min = indent;
  }
  if (!Number.isFinite(min) || min === 0) return text;
  return lines2.map((line) => line.trim() ? line.slice(min) : line).join("\n");
}
function extractTestBlocks(raw2) {
  const text = stripFences3(raw2.replace(/\r\n/g, "\n"));
  const lines2 = text.split("\n");
  const first = lines2.findIndex((line) => /^\s*test\s+"/.test(line));
  if (first < 0) return "";
  let last = -1;
  for (let i = lines2.length - 1; i > first; i--) {
    if (/^\s*end\b/.test(lines2[i])) {
      last = i;
      break;
    }
  }
  if (last < 0) return "";
  return dedent(lines2.slice(first, last + 1).join("\n")).replace(/\s+$/, "");
}
function countTests(testSource) {
  return (testSource.match(/^test\s+"/gm) ?? []).length;
}
function composeTestProgram(source, testSource) {
  return `${source.replace(/\s+$/, "")}

${testSource.trim()}
`;
}
function isRunnableSource(source) {
  return !/(^|\n)\s*(service|publish)\b/.test(source);
}

// test/aitestgen.test.ts
describe("buildTestGenMessages", () => {
  test("teaches the real Zornux test syntax and forbids prose/fences", () => {
    const { system, messages } = buildTestGenMessages("function add", "m.zx", "add");
    expect(system).toContain('test "describes the case"');
    expect(system).toContain("column 0");
    expect(system).toContain("no Markdown code fences");
    expect(messages[0].content).toContain("Focus on the function `add`");
    expect(messages[0].content).toContain("m.zx");
  });
});
describe("dedent", () => {
  test("removes the common leading indentation", () => {
    expect(dedent("    a\n    b")).toBe("a\nb");
    expect(dedent("  a\n    b")).toBe("a\n  b");
  });
  test("leaves unindented text alone", () => {
    expect(dedent("a\nb")).toBe("a\nb");
  });
});
describe("extractTestBlocks", () => {
  test("pulls test blocks out of fenced, prose-wrapped output", () => {
    const reply = 'Here you go:\n```zornux\ntest "combines"\n    expect combine(2, 3) to equal 5\nend\n\ntest "zero"\n    expect combine(0, 0) to equal 0\nend\n```\nHope this helps!';
    const extracted = extractTestBlocks(reply);
    expect(extracted.startsWith('test "combines"')).toBe(true);
    expect(extracted.includes("```")).toBe(false);
    expect(extracted.includes("Hope")).toBe(false);
    expect(countTests(extracted)).toBe(2);
  });
  test("dedents uniformly-indented blocks to column 0", () => {
    const reply = '    test "x"\n        expect 1 to equal 1\n    end';
    const extracted = extractTestBlocks(reply);
    expect(extracted).toBe('test "x"\n    expect 1 to equal 1\nend');
  });
  test("returns empty when there are no test blocks", () => {
    expect(extractTestBlocks("no tests here")).toBe("");
    expect(extractTestBlocks('test "unterminated"\n    expect 1 to equal 1')).toBe("");
  });
});
describe("composeTestProgram & isRunnableSource", () => {
  test("appends tests after the source", () => {
    const program = composeTestProgram("function add with a, b\n    give back a + b\nend", 'test "t"\n    expect add(1,1) to equal 2\nend');
    expect(program.indexOf("give back a + b")).toBeLessThan(program.indexOf("expect add"));
    expect(program.endsWith("\n")).toBe(true);
  });
  test("flags service/publish sources as not auto-runnable", () => {
    expect(isRunnableSource("function add with a\n    give back a\nend")).toBe(true);
    expect(isRunnableSource("service Greeter\nend")).toBe(false);
    expect(isRunnableSource('publish "x"')).toBe(false);
  });
});

// src/renderer/ai/debugassist.ts
function extractSnippet(source, line1, radius = 3) {
  const lines2 = source.split("\n");
  const idx = Math.max(0, Math.min(line1 - 1, lines2.length - 1));
  const from = Math.max(0, idx - radius);
  const to = Math.min(lines2.length - 1, idx + radius);
  const width = String(to + 1).length;
  const out = [];
  for (let i = from; i <= to; i++) {
    const marker = i === idx ? ">" : " ";
    const num5 = String(i + 1).padStart(width, " ");
    out.push(`${marker} ${num5} | ${lines2[i]}`);
  }
  return out.join("\n");
}
function pickNearestDiagnostic(diagnostics, cursorLine1) {
  if (diagnostics.length === 0) return null;
  let best = diagnostics[0];
  let bestDist = Math.abs(diagnostics[0].range.start.line - cursorLine1);
  for (const diagnostic2 of diagnostics) {
    const dist = Math.abs(diagnostic2.range.start.line - cursorLine1);
    if (dist < bestDist) {
      best = diagnostic2;
      bestDist = dist;
    }
  }
  return best;
}
function diagnosticToContext(diagnostic2, source, fileName) {
  return {
    kind: "diagnostic",
    message: diagnostic2.message,
    code: diagnostic2.code,
    help: diagnostic2.help,
    file: fileName,
    line: diagnostic2.range.start.line,
    snippet: extractSnippet(source, diagnostic2.range.start.line)
  };
}
function summarizeContext(context) {
  const code = context.code ? `[${context.code}] ` : "";
  const where = context.line ? ` (line ${context.line})` : "";
  return `${code}${context.message}${where}`;
}
function buildDebugMessages(context, fileName) {
  const system = [
    "You are a debugging assistant for the Zornux language (.zx).",
    "Given an error, explain the most likely cause in plain language, then give a concrete fix.",
    "Show the corrected Zornux code when it helps. Be concise and specific to the code shown \u2014 do not speculate beyond it."
  ].join("\n");
  const parts = [];
  if (fileName) parts.push(`File: ${fileName}`);
  const kindLabel = context.kind === "diagnostic" ? "Compiler error" : context.kind === "exception" ? "Runtime exception" : context.kind === "testFailure" ? "Test failure" : "Program output";
  parts.push(`${kindLabel}${context.code ? ` [${context.code}]` : ""}: ${context.message}`);
  if (context.help) parts.push(`Compiler hint: ${context.help}`);
  if (context.line) parts.push(`Location: line ${context.line}`);
  if (context.snippet) parts.push(`
Code:
${context.snippet}`);
  parts.push("\nExplain the cause and how to fix it.");
  return { system, messages: [{ role: "user", content: parts.join("\n") }] };
}

