// src/renderer/ai/architecture.ts
var STRUCTURAL_KINDS = [
  "class",
  "record",
  "repository",
  "service",
  "application",
  "migration",
  "database",
  "enum",
  "function"
];
var TOP_DECL_RE = new RegExp(`^(${STRUCTURAL_KINDS.join("|")})\\b\\s*([A-Za-z_]\\w*)?`);
var MODULE_RE2 = /^module\s+([A-Za-z_][\w.]*)/;
function scanFileDeclarations(text) {
  let module2 = null;
  const declarations = [];
  for (const line of text.split("\n")) {
    const mod2 = line.match(MODULE_RE2);
    if (mod2) module2 = mod2[1];
    const match2 = line.match(TOP_DECL_RE);
    if (match2 && match2[2]) declarations.push({ kind: match2[1], name: match2[2] });
  }
  return { module: module2, declarations };
}
function scanProject(files) {
  return files.map(({ file: file2, text }) => {
    const { module: module2, declarations } = scanFileDeclarations(text);
    return { file: file2, module: module2, declarations };
  });
}
function buildProjectMap(archs) {
  const byKind = {};
  let componentCount = 0;
  for (const arch of archs) {
    for (const decl of arch.declarations) {
      byKind[decl.kind] = (byKind[decl.kind] ?? 0) + 1;
      componentCount++;
    }
  }
  return { fileCount: archs.length, byKind, componentCount, files: archs };
}
function base(path2) {
  return path2.split(/[\\/]/).pop() ?? path2;
}
function summarizeProjectMap(map, graph, maxFiles = 60, maxEdges = 40) {
  const lines2 = [];
  lines2.push(`Project: ${map.fileCount} file${map.fileCount === 1 ? "" : "s"}, ${map.componentCount} top-level components.`);
  const kinds = Object.entries(map.byKind).sort((a, b) => b[1] - a[1]).map(([kind, count]) => `${kind} \xD7${count}`);
  if (kinds.length) lines2.push(`Components by kind: ${kinds.join(", ")}.`);
  lines2.push("", "Files:");
  for (const file2 of map.files.slice(0, maxFiles)) {
    const decls = file2.declarations.map((d2) => `${d2.kind} ${d2.name}`).join(", ") || "(no top-level components)";
    const mod2 = file2.module ? ` [module ${file2.module}]` : "";
    lines2.push(`- ${file2.file}${mod2}: ${decls}`);
  }
  if (map.files.length > maxFiles) lines2.push(`- \u2026 and ${map.files.length - maxFiles} more files`);
  if (graph) {
    const edgeEntries = Object.entries(graph.edges).filter(([, targets]) => targets.length > 0);
    if (edgeEntries.length) {
      lines2.push("", "Module dependencies (file \u2192 imports):");
      for (const [from, targets] of edgeEntries.slice(0, maxEdges)) {
        lines2.push(`- ${base(from)} \u2192 ${targets.map(base).join(", ")}`);
      }
      if (edgeEntries.length > maxEdges) lines2.push(`- \u2026 and ${edgeEntries.length - maxEdges} more`);
    }
    if (graph.cycles.length) {
      lines2.push("", `Import cycles: ${graph.cycles.map((cycle) => cycle.map(base).join(" \u2192 ")).join(" | ")}`);
    }
    if (graph.unresolved.length) {
      lines2.push(`Unresolved imports: ${graph.unresolved.length} (e.g. ${graph.unresolved.slice(0, 3).map((u) => u.module).join(", ")})`);
    }
    if (graph.duplicateModules.length) {
      lines2.push(`Duplicate module declarations: ${graph.duplicateModules.map((d2) => d2.module).join(", ")}`);
    }
  }
  return lines2.join("\n");
}
function buildArchitectureMessages(summary, projectName) {
  const system = [
    "You are a software architect reviewing a Zornux project (an English-readable, statically-typed language).",
    "From the provided map of files, components, and module dependencies, describe the architecture:",
    "the layers and responsibilities you can infer, how components relate, and the overall shape.",
    "Then note strengths, risks (tight coupling, import cycles, god-modules, missing layers, unresolved imports),",
    "and give concrete, prioritized recommendations.",
    "Ground everything in the map \u2014 do not invent files or components that are not listed."
  ].join("\n");
  const name = projectName ? `Project: ${projectName}

` : "";
  return { system, messages: [{ role: "user", content: `${name}${summary}` }] };
}

