  const parts = [
    `File: ${ctx.file}`,
    `Diagnostic [${ctx.code}] (${ctx.severity}): ${ctx.message}`
  ];
  if (ctx.hint) parts.push(`Compiler hint: ${ctx.hint}`);
  parts.push(`Location: line ${ctx.line}`, "", "Code:", region);
