function searchMarketplace(entries, query) {
  const q = query.trim().toLowerCase();
  if (!q) return sortMarketplace(entries, "installs");
  const scored = [];
  for (const entry4 of entries) {
    const name = entry4.name.toLowerCase();
    const haystack = [name, entry4.publisher, entry4.description, ...entry4.categories].join(" ").toLowerCase();
    let score;
    if (name.startsWith(q)) score = 0;
    else if (name.includes(q)) score = 1;
    else if (haystack.includes(q)) score = 2;
    else continue;
    scored.push({ entry: entry4, score });
  }
  return scored.sort((a, b) => a.score - b.score || (b.entry.installs ?? 0) - (a.entry.installs ?? 0)).map((s) => s.entry);
}
function sortMarketplace(entries, by) {
  const copy = [...entries];
  switch (by) {
    case "installs":
      return copy.sort((a, b) => (b.installs ?? 0) - (a.installs ?? 0));
    case "rating":
      return copy.sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0));
    case "name":
      return copy.sort((a, b) => a.name.localeCompare(b.name));
  }
}
