// src/renderer/extensions/DeclarativeContributions.ts
function applyContributions(context, ext2) {
  const disposables = [];
  const { commands, services } = context;
  const contributableOwn = new Set(ext2.contributions.commands.map((c) => c.command));
  for (const c of ext2.contributions.commands) {
    if (!EXTENSION_CONTRIBUTABLE_COMMANDS.includes(c.runs)) continue;
    try {
      disposables.push(commands.register(c.command, () => commands.execute(c.runs), c.title));
    } catch {
    }
  }
  const snippetService = services.tryGet(ServiceKeys.Snippets);
  if (snippetService && ext2.contributions.snippets.length) {
    disposables.push(
      snippetService.addExternal(
        ext2.contributions.snippets.map((s) => ({
          name: s.prefix,
          prefix: s.prefix,
          description: s.description ?? "",
          body: s.body,
          languages: [s.language]
        }))
      )
    );
  }
  const keybindings = services.tryGet(ServiceKeys.Keybindings);
  if (keybindings) {
    for (const kb of ext2.contributions.keybindings) {
      if (!EXTENSION_CONTRIBUTABLE_COMMANDS.includes(kb.command) && !contributableOwn.has(kb.command)) continue;
      try {
        disposables.push(keybindings.registerExternal(kb.key, kb.command));
      } catch {
      }
    }
  }
  const theme = services.tryGet(ServiceKeys.Theme);
  if (theme) {
    for (const t of ext2.contributions.themes) {
      disposables.push(theme.register({ id: t.id, label: t.label, type: t.type, cssVars: t.cssVars }));
    }
  }
  return {
    dispose: () => {
      for (const d2 of disposables.reverse()) {
        try {
          d2.dispose();
        } catch {
        }
      }
    }
  };
}

