var FIELD = "";
var LOG_FORMAT = `--pretty=format:%H${FIELD}%h${FIELD}%an${FIELD}%ad${FIELD}%s`;
function parseLog(output) {
  const commits = [];
  for (const line of output.split("\n")) {
    if (!line.trim()) continue;
    const parts = line.split(FIELD);
    if (parts.length < 5) continue;
    commits.push({
      hash: parts[0],
      shortHash: parts[1],
      author: parts[2],
      date: parts[3],
      subject: parts.slice(4).join(FIELD)
    });
  }
  return commits;
}
function parseNumstat(output) {
  const files = [];
  for (const line of output.split("\n")) {
    const match2 = line.match(/^(\d+|-)\t(\d+|-)\t(.+)$/);
    if (!match2) continue;
    const binary = match2[1] === "-" && match2[2] === "-";
    files.push({
      additions: match2[1] === "-" ? 0 : Number(match2[1]),
      deletions: match2[2] === "-" ? 0 : Number(match2[2]),
      binary,
      path: match2[3]
    });
  }
  return files;
}
function diffStat(files) {
  return files.reduce(
    (acc, file2) => ({
      additions: acc.additions + file2.additions,
      deletions: acc.deletions + file2.deletions,
      files: acc.files + 1
    }),
    { additions: 0, deletions: 0, files: 0 }
  );
}

