// src/renderer/deploy/kubernetes.ts
function k8sName(context) {
  return context.projectName.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "") || "app";
}
function envBlock(envVars, indent) {
  const keys = Object.keys(envVars);
  if (keys.length === 0) return "";
  const lines2 = keys.map((key2) => `${indent}- name: ${key2}
${indent}  value: ${JSON.stringify(envVars[key2])}`);
  return `${indent.slice(0, -2)}env:
${lines2.join("\n")}
`;
}
function generateManifests(context) {
  const name = k8sName(context);
  const image = imageTag(context);
  const replicas = context.environment === "production" ? 2 : 1;
  const env = envBlock(context.envVars, "            ");
  return `# Generated by ZnxStudio for ${context.projectName} (${context.environment})
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${name}
  labels:
    app: ${name}
spec:
  replicas: ${replicas}
  selector:
    matchLabels:
      app: ${name}
  template:
    metadata:
      labels:
        app: ${name}
    spec:
      containers:
        - name: ${name}
          image: ${image}
          ports:
            - containerPort: ${context.port}
${env}          resources:
            requests:
              cpu: "100m"
              memory: "128Mi"
            limits:
              cpu: "500m"
              memory: "256Mi"
---
apiVersion: v1
kind: Service
metadata:
  name: ${name}
  labels:
    app: ${name}
spec:
  selector:
    app: ${name}
  ports:
    - port: 80
      targetPort: ${context.port}
  type: ClusterIP
`;
}
function parseKubectlGet(output) {
  const rows = [];
  const lines2 = output.split("\n");
  for (const line of lines2) {
    if (!line.trim()) continue;
    const cols = line.trim().split(/\s+/);
    if (cols[0] === "NAME") continue;
    if (cols.length < 3) continue;
    rows.push({
      name: cols[0],
      ready: cols[1],
      status: cols[2],
      restarts: cols[3] ?? "",
      age: cols[4] ?? ""
    });
  }
  return rows;
}

