    truncated: false,
    types: [{ type: "Number", count: 500 }, { type: "Text", count: 20 }],
    classes: [{ class: "Customer", count: customers }, { class: "Order", count: 10 }],
    topContainers: [{ kind: "List", size: 42 }, { kind: "Map", size: 7 }],
