// test/shells.test.ts
describe("shell discovery (pure candidates)", () => {
  test("windows offers powershell, pwsh, cmd, git-bash and wsl", () => {
    const env = {
      SystemRoot: "C:\\Windows",
      ProgramFiles: "C:\\Program Files",
      "ProgramFiles(x86)": "C:\\Program Files (x86)",
      LOCALAPPDATA: "C:\\Users\\me\\AppData\\Local"
    };
    const ids = candidateShells("win32", env).map((c) => c.id);
    expect(ids).toEqual(["powershell", "pwsh", "cmd", "git-bash", "wsl"]);
  });
  test("windows powershell is the default (first) and resolves under System32", () => {
    const cands = candidateShells("win32", { SystemRoot: "C:\\Windows" });
    expect(cands[0].id).toBe("powershell");
    expect(cands[0].paths[0]).toBe("C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe");
    const cmd = cands.find((c) => c.id === "cmd");
    expect(cmd?.paths[0]).toBe("C:\\Windows\\System32\\cmd.exe");
  });
  test("windows falls back to default program-files locations when env is bare", () => {
    const cands = candidateShells("win32", {});
    const pwsh = cands.find((c) => c.id === "pwsh");
    expect(pwsh?.paths).toContain("C:\\Program Files\\PowerShell\\7\\pwsh.exe");
    const git = cands.find((c) => c.id === "git-bash");
    expect(git?.paths[0]).toBe("C:\\Program Files\\Git\\bin\\bash.exe");
  });
  test("unix puts $SHELL first as the default and still offers common shells", () => {
    const cands = candidateShells("linux", { SHELL: "/usr/bin/zsh" });
    expect(cands[0].id).toBe("zsh");
    expect(cands[0].paths).toEqual(["/usr/bin/zsh"]);
    const ids = cands.map((c) => c.id);
    expect(ids).toContain("bash");
    expect(ids).toContain("fish");
    expect(ids).toContain("sh");
  });
  test("unix without $SHELL leads with zsh then bash and probes homebrew paths", () => {
    const cands = candidateShells("darwin", {});
    expect(cands[0].id).toBe("zsh");
    const bash = cands.find((c) => c.id === "bash");
    expect(bash?.paths).toContain("/opt/homebrew/bin/bash");
  });
  test("every candidate carries an id, label, args array and at least one path", () => {
    for (const platform of ["win32", "linux", "darwin"]) {
      for (const c of candidateShells(platform, { SHELL: "/bin/bash" })) {
        expect(Boolean(c.id)).toBe(true);
        expect(Boolean(c.label)).toBe(true);
        expect(Array.isArray(c.args)).toBe(true);
        expect(c.paths.length > 0).toBe(true);
      }
    }
  });
});

// src/renderer/terminal/split.ts
function resizeSplit(sizeBefore, sizeAfter, growBefore, growAfter, delta, min = 60) {
  const totalPx = sizeBefore + sizeAfter;
  const totalGrow = growBefore + growAfter;
  if (totalPx <= 0 || totalGrow <= 0) return { before: growBefore, after: growAfter };
  const clampedMin = Math.min(min, totalPx / 2);
  let newBefore = sizeBefore + delta;
  newBefore = Math.max(clampedMin, Math.min(totalPx - clampedMin, newBefore));
  const before = totalGrow * (newBefore / totalPx);
  return { before, after: totalGrow - before };
}

// test/terminalsplit.test.ts
describe("split divider geometry (resizeSplit)", () => {
  test("a zero drag leaves the weights unchanged", () => {
    const r = resizeSplit(300, 300, 1, 1, 0);
    expect(Math.round(r.before * 1e3) / 1e3).toBe(1);
    expect(Math.round(r.after * 1e3) / 1e3).toBe(1);
  });
  test("dragging right grows the left pane and shrinks the right, sum preserved", () => {
    const r = resizeSplit(300, 300, 1, 1, 60);
    expect(r.before > 1).toBe(true);
    expect(r.after < 1).toBe(true);
    expect(Math.round((r.before + r.after) * 1e3) / 1e3).toBe(2);
    expect(Math.round(r.before * 100) / 100).toBe(1.2);
  });
  test("the left pane cannot shrink below the minimum", () => {
    const r = resizeSplit(300, 300, 1, 1, -1e3, 60);
    expect(Math.round(r.before * 100) / 100).toBe(0.2);
    expect(Math.round((r.before + r.after) * 1e3) / 1e3).toBe(2);
  });
  test("the right pane cannot shrink below the minimum", () => {
    const r = resizeSplit(300, 300, 1, 1, 1e3, 60);
    expect(Math.round(r.after * 100) / 100).toBe(0.2);
  });
  test("preserves an uneven total grow weight", () => {
    const r = resizeSplit(200, 400, 1, 2, 100);
    expect(Math.round((r.before + r.after) * 1e3) / 1e3).toBe(3);
    expect(Math.round(r.before * 100) / 100).toBe(1.5);
  });
  test("degenerate zero-size pair is a no-op (avoids divide-by-zero)", () => {
    const r = resizeSplit(0, 0, 1, 1, 50);
    expect(r.before).toBe(1);
    expect(r.after).toBe(1);
  });
});

// src/renderer/terminal/inputBuffer.ts
var MAX_BUFFERED_INPUT = 64 * 1024;
var TerminalInputBuffer = class {
  chunks = [];
  length = 0;
  ready = false;
  closed = false;
  accept(data, send) {
    if (this.closed || !data) return;
    if (this.ready) {
      send(data);
      return;
    }
    const remaining = MAX_BUFFERED_INPUT - this.length;
    if (remaining <= 0) return;
    const chunk = data.slice(0, remaining);
    this.chunks.push(chunk);
    this.length += chunk.length;
  }
  markReady(send) {
    if (this.closed || this.ready) return;
    this.ready = true;
    const buffered = this.chunks.join("");
    this.chunks = [];
    this.length = 0;
    if (buffered) send(buffered);
  }
  close() {
    this.closed = true;
    this.chunks = [];
    this.length = 0;
  }
};

// src/main/services/terminalSessionKey.ts
function terminalSessionKey(ownerId, terminalId) {
  return `${ownerId}:${terminalId}`;
}

// src/renderer/terminal/terminalShortcuts.ts
function resolveTerminalShortcut(event, isMac) {
  const key2 = event.key.toLowerCase();
  const noAlt = !event.altKey;
  if (noAlt && event.ctrlKey && !event.metaKey && key2 === "pagedown") return "next-tab";
  if (noAlt && event.ctrlKey && !event.metaKey && key2 === "pageup") return "previous-tab";
  if (noAlt && event.ctrlKey && event.shiftKey && !event.metaKey && key2 === "c") return "copy";
  if (noAlt && event.ctrlKey && event.shiftKey && !event.metaKey && key2 === "v") return "paste";
  if (noAlt && event.ctrlKey && !event.shiftKey && !event.metaKey && key2 === "insert") return "copy";
  if (noAlt && event.shiftKey && !event.ctrlKey && !event.metaKey && key2 === "insert") return "paste";
  if (isMac && noAlt && event.metaKey && !event.ctrlKey && key2 === "c") return "copy";
  if (isMac && noAlt && event.metaKey && !event.ctrlKey && key2 === "v") return "paste";
  return "shell";
}

// test/terminalinput.test.ts
var key = (keyName, modifiers = {}) => ({
  key: keyName,
  ctrlKey: false,
  metaKey: false,
  shiftKey: false,
  altKey: false,
  ...modifiers
});
describe("terminal interactive input", () => {
  test("preserves typing and paste entered before the PTY is ready", () => {
    const input = new TerminalInputBuffer();
    const sent = [];
    const send = (data) => {
      sent.push(data);
    };
    input.accept("Ada", send);
    input.accept("\r", send);
    expect(sent).toEqual([]);
    input.markReady(send);
    input.accept("next", send);
    expect(sent).toEqual(["Ada\r", "next"]);
  });
  test("drops buffered and future input after a process exits", () => {
    const input = new TerminalInputBuffer();
    const sent = [];
    input.accept("secret", (data) => sent.push(data));
    input.close();
    input.markReady((data) => sent.push(data));
    input.accept("ignored", (data) => sent.push(data));
    expect(sent).toEqual([]);
  });
  test("bounds startup input buffering", () => {
    const input = new TerminalInputBuffer();
    const sent = [];
    input.accept("x".repeat(1e5), (data) => sent.push(data));
    input.markReady((data) => sent.push(data));
    expect(sent[0].length).toBe(64 * 1024);
  });
  test("scopes identical terminal ids to their owning window", () => {
    expect(terminalSessionKey(1, "term-1")).toBe("1:term-1");
    expect(terminalSessionKey(2, "term-1")).toBe("2:term-1");
  });
  test("keeps common shell control keys in the PTY", () => {
    for (const name of ["c", "d", "l", "r", "z", "ArrowUp", "ArrowDown"]) {
      expect(resolveTerminalShortcut(key(name, { ctrlKey: true }), false)).toBe("shell");
    }
  });
  test("recognizes cross-platform clipboard shortcuts", () => {
    expect(resolveTerminalShortcut(key("c", { ctrlKey: true, shiftKey: true }), false)).toBe("copy");
    expect(resolveTerminalShortcut(key("v", { ctrlKey: true, shiftKey: true }), false)).toBe("paste");
    expect(resolveTerminalShortcut(key("Insert", { ctrlKey: true }), false)).toBe("copy");
    expect(resolveTerminalShortcut(key("Insert", { shiftKey: true }), false)).toBe("paste");
    expect(resolveTerminalShortcut(key("c", { metaKey: true }), true)).toBe("copy");
    expect(resolveTerminalShortcut(key("v", { metaKey: true }), true)).toBe("paste");
    expect(resolveTerminalShortcut(key("c", { metaKey: true }), false)).toBe("shell");
  });
  test("switches terminal tabs without sending PageUp or PageDown to the shell", () => {
    expect(resolveTerminalShortcut(key("PageDown", { ctrlKey: true }), false)).toBe("next-tab");
    expect(resolveTerminalShortcut(key("PageUp", { ctrlKey: true }), false)).toBe("previous-tab");
    expect(resolveTerminalShortcut(key("PageDown"), false)).toBe("shell");
  });
});

