var active = null;
function claimOverlay(owner, dismiss) {
  if (active?.owner !== owner) active?.dismiss();
  active = { owner, dismiss };
  return () => {
    if (active?.owner === owner) active = null;
  };
}
function dismissActiveOverlay() {
  const current = active;
  active = null;
  current?.dismiss();
}

// test/overlaycoordinator.test.ts
describe("overlay coordinator", () => {
  test("a new owner dismisses the previous owner exactly once", () => {
    let firstDismissals = 0;
    const releaseFirst = claimOverlay({}, () => {
      firstDismissals += 1;
    });
    const releaseSecond = claimOverlay({}, () => void 0);
    expect(firstDismissals).toBe(1);
    releaseFirst();
    releaseSecond();
  });
  test("releasing an old claim cannot clear the current owner", () => {
    let currentDismissals = 0;
    const releaseOld = claimOverlay({}, () => void 0);
    claimOverlay({}, () => {
      currentDismissals += 1;
    });
    releaseOld();
    dismissActiveOverlay();
    expect(currentDismissals).toBe(1);
  });
});

