var ICON_BY_EXTENSION = {
  ts: "TS",
  tsx: "TX",
  js: "JS",
  jsx: "JX",
  json: "{}",
  md: "M\u2193",
  css: "#",
  scss: "S#",
  html: "<>",
  zx: "Z",
  zornux: "Z",
  zoijs: "Zo",
  png: "\u25A3",
  jpg: "\u25A3",
  jpeg: "\u25A3",
  svg: "\u25C7",
  gitignore: "\u2298"
};
var ICON_BY_NAME = {
  "znxstudio.project.json": "Z",
  "package.json": "P",
  "readme.md": "R"
};
function fileIcon(name) {
  const byName = ICON_BY_NAME[name.toLowerCase()];
  if (byName) return byName;
  const extension = name.split(".").pop()?.toLowerCase() ?? "";
  return ICON_BY_EXTENSION[extension] ?? "\u25A1";
}
function folderIconClass(expanded = false) {
  return `znxstudio-folder-icon${expanded ? " is-open" : ""}`;
}

