describe("stress \u2014 editor tabs (20E)", () => {
  test("2000 opens keep every invariant and the last is active", () => {
    let state = EMPTY_TABS;
    for (let i = 0; i < 2e3; i += 1) state = openTab(state, entry3(i), { preview: false });
    expect(state.tabs).toHaveLength(2e3);
    expect(state.activeUri).toBe(entry3(1999).uri);
    assertTabInvariants(state);
  });
  test("a mixed pin/dirty/close storm drains cleanly to zero", () => {
    let state = EMPTY_TABS;
    for (let i = 0; i < 800; i += 1) state = openTab(state, entry3(i), { preview: false });
    for (let i = 0; i < 800; i += 3) state = pinTab(state, entry3(i).uri);
    for (let i = 1; i < 800; i += 2) state = markDirty(state, entry3(i).uri, true);
    assertTabInvariants(state);
    let guard = 0;
    while (state.activeUri && guard < 5e3) {
      state = closeTab(state, state.activeUri);
      assertTabInvariants(state);
      guard += 1;
    }
    expect(state.tabs.length).toBe(0);
  });
  test("closeOthers on 1000 tabs keeps only the target + pinned", () => {
    let state = EMPTY_TABS;
    for (let i = 0; i < 1e3; i += 1) state = openTab(state, entry3(i), { preview: false });
    for (let i = 0; i < 1e3; i += 10) state = pinTab(state, entry3(i).uri);
    state = closeOthers(state, entry3(7).uri);
    expect(state.tabs).toHaveLength(101);
    assertTabInvariants(state);
    expect(closeAll(state).tabs.every((t) => t.pinned)).toBe(true);
  });
});
