    preview: { version: "1.1.0-rc.2", url: "https://dl/z-1.1.0-rc.2.exe", sha512: "BBB" },
    nightly: { version: "1.2.0-nightly.5", url: "https://dl/z-nightly.exe", sha512: "CCC" }
